#!/bin/bash
# Autogenerated deployment script for rsu-tax-optimizer
set -e
cd "$(dirname "$0")"

echo "=== Building web client for rsu-tax-optimizer ==="
cd web
npm install
npm run build
cd ..

echo "=== Deploying to Hostinger via rsync ==="
# Note: Ensure you have added 'hostinger-portfolio' to your SSH config.
# If using env vars: rsync -avz --delete web/dist/ $HOSTINGER_USER@$HOSTINGER_HOST:/home/u918475266/public_html/rsu-tax-optimizer/
rsync -avz --delete web/dist/ hostinger-portfolio:/home/u918475266/public_html/rsu-tax-optimizer/

echo "=== Deployment for rsu-tax-optimizer completed successfully ==="
